guided-practice.solution:
def running_total(numbers):
    total = 0
    for n in numbers:
        total += n
        yield total

def evens_from(start):
    n = start
    if n % 2 != 0:
        n += 1
    while True:
        yield n
        n += 2

independent-practice.solution:
def first_error_line(lines):
    position = 0
    for line in lines:
        if "ERROR" in line:
            return position
        position += 1
    return -1

def chunked(values, size):
    batch = []
    for value in values:
        batch.append(value)
        if len(batch) == size:
            yield batch
            batch = []
    if batch:
        yield batch

def above_average(readings):
    values = list(readings)
    if not values:
        return []
    mean = sum(values) / len(values)
    return [v for v in values if v > mean]

def unique(values):
    seen = set()
    for value in values:
        if value not in seen:
            seen.add(value)
            yield value

def deltas(readings):
    previous = None
    started = False
    for value in readings:
        if started:
            yield value - previous
        previous = value
        started = True

